import React, { useState, useRef } from "react";
import { useNavigate } from "react-router-dom";
import MoonLoader from "react-spinners/MoonLoader";

import "./Upload.css";

// The rubric prompt as shown in your screenshot
const rubricPrompt = `
Rubric: Clarity (0-5), Structure (0-5), Creativity (0-5)

Example 1:
Script: "The moon was bright. She walked alone under it..."
Score: Clarity: 4, Structure: 3, Creativity: 5

Example 2:
Script: "I go to school. It is good. I learn."
Score: Clarity: 3, Structure: 2, Creativity: 2

Now evaluate this script:
Script: `;

function Upload() {
  const [videoFile, setVideoFile] = useState(null);
  const [rubricFile, setRubricFile] = useState(null);
  const [rubricFileName, setRubricFileName] = useState("");
  const [transcript, setTranscript] = useState("");
  const [feedback, setFeedback] = useState("");
  const [rubricScore, setRubricScore] = useState(""); // NEW: rubric evaluation result
  const [loading, setLoading] = useState(false);
  const [analysis, setAnalysis] = useState({});
  const [status, setStatus] = useState("");

  const navigate = useNavigate();
  const rubricInputRef = useRef(null);

  const handleFileChange = (event) => {
    setVideoFile(event.target.files[0]);
  };

  // Accept .txt rubric file
  const handleRubricUpload = (event) => {
    const file = event.target.files[0];
    if (file && file.type === "text/plain") {
      setRubricFile(file);
      setRubricFileName(file.name);
      console.log("Rubric file uploaded:", file.name);
    } else {
      console.error("Please upload a valid .txt file.");
    }
  };

  // Send transcript to /evaluate with the rubric prompt, show result
  const handleRubricEvaluation = async (scriptText) => {
    // Read rubric file text if provided, otherwise use default rubricPrompt
    let rubricText = rubricPrompt;
    if (rubricFile) {
      rubricText = await rubricFile.text();
      // If you want to append the few-shot examples, you can concatenate here.
      // rubricText += "\n\n" + rubricPrompt; // Optional
    }
    const prompt = `${rubricText}\nScript: "${scriptText}"\nScore:`;

    try {
      const response = await fetch("http://34.55.142.231:5000/evaluate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ script_text: scriptText, prompt: prompt }),
      });
      const data = await response.json();
      setRubricScore(data.evaluation || data.result || "No evaluation returned.");
    } catch (error) {
      setRubricScore("Error with rubric evaluation.");
    }
  };

  const handleAnalyze = async () => {
    console.log("Start analyzing...");

    // Check if user is logged in
    const userId = localStorage.getItem("user_id");
    if (!userId) {
      alert("You must be logged in to upload and analyze videos.");
      navigate("/login");  // Redirect to login page
      return;
    }

    if (!videoFile) {
      alert("Please upload a video before analyzing.");
      return;
    }

    setStatus("processing");
    setLoading(true);

    const formData = new FormData();
    formData.append("video", videoFile);

    try {
      const response = await fetch("http://34.55.142.231:5000/transcribe", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        const errMsg = errorData.error || "Error processing video. Please try again.";
        setTranscript(errMsg);
        setLoading(false);
        setStatus("");
        return;
      }

      const data = await response.json();
      console.log("Analysis Data:", data);

      const videoFilename = data.video_filename;
      const aiFeedback = data.ai_feedback;

      await fetch("http://34.55.142.231:5000/save-video", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          user_id: userId,
          video_filename: videoFilename,
          feedback: aiFeedback,
        }),
      });

      setTranscript(data.transcript);
      setFeedback(data.ai_feedback);
      setAnalysis(data);

      setLoading(false);
      setStatus("");

      // If rubric file is uploaded, automatically evaluate with rubric
      if (rubricFile) {
        handleRubricEvaluation(data.transcript);
      }

      // Success: redirect to Library
      navigate("/library");
    } catch (error) {
      console.error("Error analyzing video:", error);
      setFeedback("Error processing video. Please try again.");
      setLoading(false);
      setStatus("");
    }
  };

  return (
    <div className="dashboard-container">
      <h1 className="page-title">Video Analysis Dashboard</h1>

      {videoFile && status === "processing" ? (
        <div className="dashboard-content">
          <div className="loader-div">
            <MoonLoader size={50} color="#77232C" />
          </div>
        </div>
      ) : (
        <div className="upload-content">
          <div className="upload-div">
            {videoFile ? (
              <video controls>
                <source src={URL.createObjectURL(videoFile)} type={videoFile.type} />
                Your browser does not support the video tag.
              </video>
            ) : (
              <input type="file" accept="video/*" onChange={handleFileChange} />
            )}

            <button className="save-button" onClick={handleAnalyze} disabled={loading}>
              Analyze Video
            </button>

            <div style={{ marginTop: "10px" }}>
              <input
                ref={rubricInputRef}
                type="file"
                accept=".txt"
                id="rubric-upload"
                onChange={handleRubricUpload}
                style={{ display: "none" }}
              />
              <button
                className="save-button"
                type="button"
                onClick={() => rubricInputRef.current && rubricInputRef.current.click()}
              >
                Upload Rubric
              </button>
            </div>

            {rubricFileName && (
              <p style={{ marginTop: "10px", color: "#77232C", fontWeight: "bold" }}>
                Uploaded Rubric: {rubricFileName}
              </p>
            )}

            {/* Show transcript and feedback */}
            {transcript && (
              <div style={{ marginTop: "20px" }}>
                <h3>Transcript</h3>
                <pre>{transcript}</pre>
                <h3>AI Feedback</h3>
                <pre>{feedback}</pre>
              </div>
            )}

            {/* Show rubric evaluation if available */}
            {rubricScore && (
              <div style={{ marginTop: "20px" }}>
                <h3>Rubric Score</h3>
                <pre>{rubricScore}</pre>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default Upload;
